parameters.jsCode:
// Découpe le XML PubMed (efetch) en documents prêts à être vectorisés
const xml = $input.first().json.data || '';

// Retire les balises internes (<i>, <sup>...) puis décode les entités HTML
const decode = (s) => s
  .replace(/<[^>]+>/g, '')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'")
  .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
  .replace(/&amp;/g, '&')
  .replace(/\s+/g, ' ')
  .trim();

const blocs = xml.match(/<PubmedArticle>[\s\S]*?<\/PubmedArticle>/g) || [];

const ids = [];
const documents = [];
const metadatas = [];
let sansResume = 0;

for (const bloc of blocs) {
  const pmid = (bloc.match(/<PMID[^>]*>(\d+)<\/PMID>/) || [])[1];
  const titre = decode((bloc.match(/<ArticleTitle[^>]*>([\s\S]*?)<\/ArticleTitle>/) || [])[1] || '');
  const revue = decode((bloc.match(/<Journal>[\s\S]*?<Title>([\s\S]*?)<\/Title>/) || [])[1] || '');
  const annee = (bloc.match(/<PubDate>[\s\S]*?<Year>(\d{4})<\/Year>/) || [])[1] || '';

  // Un résumé peut être en plusieurs parties (Background, Methods, Results...)
  const parties = [...bloc.matchAll(/<AbstractText([^>]*)>([\s\S]*?)<\/AbstractText>/g)].map((m) => {
    const label = (m[1].match(/Label="([^"]*)"/) || [])[1];
    const texte = decode(m[2]);
    return label ? `${label}: ${texte}` : texte;
  });
  const resume = parties.join(' ');

  // Sans résumé, il n'y a rien d'utile à indexer
  if (!pmid || !titre || !resume) {
    sansResume++;
    continue;
  }

  ids.push(`pubmed-${pmid}`);
  documents.push(`${titre}\n\n${resume}`);
  metadatas.push({
    source: 'pubmed',
    pmid,
    titre,
    revue,
    annee,
    lien: `https://pubmed.ncbi.nlm.nih.gov/${pmid}/`,
  });
}

// Contrôle d'encodage : compte les caractères chinois parasites (accents mal décodés)
const encodageSuspect = (documents.join(' ').match(/[\u4e00-\u9fff]/g) || []).length;

// Rien à indexer cette semaine : on s'arrête sans erreur
if (documents.length === 0) return [];

return [{ json: { nombre: documents.length, sansResume, encodageSuspect, ids, documents, metadatas } }];

